import sqlite3
import subprocess
import sys

from agents import function_tool as tool

DB_PATH = "projects.db"
SCRIPT_PATH = "scripts/rollover.py"


def _revoke_temp_access(conn, sprint_id):
    cur = conn.execute(
        "DELETE FROM sprint_members WHERE sprint_id = ? AND access_type = 'temporary'",
        (sprint_id,),
    )
    return cur.rowcount


def _delete_cancelled(conn, sprint_id):
    cur = conn.execute(
        "DELETE FROM tasks WHERE sprint_id = ? AND status = 'cancelled'",
        (sprint_id,),
    )
    return cur.rowcount


@tool
def run_sprint_rollover_cleanup(sprint_id: int, next_sprint_id: int, dry_run: bool = False) -> dict:
    cmd = [
        sys.executable,
        SCRIPT_PATH,
        "--from", str(sprint_id),
        "--to", str(next_sprint_id),
    ]
    if dry_run:
        cmd.append("--dry-run")
    proc = subprocess.run(cmd, capture_output=True, text=True, timeout=300)
    if proc.returncode != 0:
        return {
            "success": False,
            "returncode": proc.returncode,
            "stderr": proc.stderr[-1000:],
        }
    if dry_run:
        return {"success": True, "dry_run": True, "output": proc.stdout[-1000:]}
    conn = sqlite3.connect(DB_PATH)
    try:
        revoked = _revoke_temp_access(conn, sprint_id)
        deleted = _delete_cancelled(conn, sprint_id)
        conn.commit()
    finally:
        conn.close()
    return {
        "success": True,
        "dry_run": False,
        "output": proc.stdout[-1000:],
        "access_revoked": revoked,
        "cancelled_tasks_deleted": deleted,
    }
